SELECT jsonb_build_object('customers',(SELECT count(*) FROM app.customer_profiles WHERE id IN ('597dd25a-072f-5fce-b142-055e2980edfb','ef2d7ed3-ee87-5bb5-aac8-343b2c272e10')),'commands',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('3efa9fb9-fe44-5c82-85c4-a56fc1ec7449','db3d7cfc-fc9f-5933-951e-a0f43fa9d09f')),'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id IN ('597dd25a-072f-5fce-b142-055e2980edfb','ef2d7ed3-ee87-5bb5-aac8-343b2c272e10')),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id IN ('597dd25a-072f-5fce-b142-055e2980edfb','ef2d7ed3-ee87-5bb5-aac8-343b2c272e10')),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE aggregate_kind='CustomerProfile' AND aggregate_id IN ('597dd25a-072f-5fce-b142-055e2980edfb','ef2d7ed3-ee87-5bb5-aac8-343b2c272e10')),'effects',(SELECT count(*) FROM platform.runtime_effect_receipt WHERE command_receipt_id IN ('3efa9fb9-fe44-5c82-85c4-a56fc1ec7449','db3d7cfc-fc9f-5933-951e-a0f43fa9d09f')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id IN ('597dd25a-072f-5fce-b142-055e2980edfb','ef2d7ed3-ee87-5bb5-aac8-343b2c272e10')));
